#nullable enable // autogenerated

using System;
using System.Collections.Generic;
using MVZ2.Managers;
using MVZ2.Resources;
using MVZ2.Sprites;
using NGettext;
using PVZEngine;
using UnityEngine;

namespace MVZ2.Localization
{
    public abstract class ResourcePackReaderV1 : ResourcePackReader
    {
        protected ResourcePackReaderV1(MainManager main) : base(main)
        {
        }
        protected Sprite CreateSprite(Texture2D texture2D, SliceData sliceData, string generatedCategory, string generatedName)
        {
            try
            {
                Rect rect;
                if (sliceData.single)
                {
                    rect = new Rect(0, 0, texture2D.width, texture2D.height);
                }
                else
                {
                    rect = sliceData.rect;
                    rect.y = SpriteHelper.FromTopToFromBottomY(rect.y, texture2D.height, rect.height);
                }
                rect.width = Math.Min(rect.width, texture2D.width);
                rect.height = Math.Min(rect.height, texture2D.height);

                var pivot = sliceData.pivot;
                var meshType = sliceData.meshType;
                var border = sliceData.border;
                var spr = Main.ResourceManager.CreateSprite(texture2D, rect, pivot, generatedName, border, meshType, category: generatedCategory);
                return spr;
            }
            catch (Exception e)
            {
                Debug.LogError($"An exception thrown when loading sprite {generatedName} from a language pack: {e}");
                return Main.ResourceManager.GetDefaultSpriteClone();
            }
        }
        protected void ApplyReadData(ResourcePack pack, PackReadData data, ReadTexture2DMethod textureReader)
        {
            ApplyReadDataCatalogs(pack, data);
            ApplyReadDataTextures(pack, data, textureReader);
        }
        private void ApplyReadDataCatalogs(ResourcePack pack, PackReadData data)
        {
            foreach (var lang in data.catalogs.Keys)
            {
                var packCatalogs = pack.GetOrCreateLanguageCatalogs(lang);
                // 加载文本
                foreach (var pair in data.catalogs[lang])
                {
                    packCatalogs.catalogs.Add(pair.Key, pair.Value);
                }
            }
        }
        private void ApplyReadDataTextures(ResourcePack pack, PackReadData data, ReadTexture2DMethod textureReader)
        {
            foreach (var textureData in data.textureEntries)
            {
                var texturePath = textureData.texturePath;
                var textureID = textureData.textureID;
                // 尝试获取资源包中的这个texture对象。
                // 如果没有获取到，新建一个。
                if (!pack.TryGetTexture2D(textureID, out var texture))
                {
                    texture = textureReader(texturePath, textureID.ToString());
                    if (texture == null)
                        continue;
                    texture.filterMode = textureData.filterMode;
                    pack.AddTexture2D(textureID, texture);
                }

                var slices = textureData.slices;
                for (int i = 0; i < slices.Count; i++)
                {
                    var slice = slices[i];
                    var sprite = CreateSprite(texture, slice, GetLanguagePackSpriteCategory(data.Key), slice.spriteKey.ToString());
                    pack.AddSprite(slice.spriteKey, sprite);
                }
            }
        }
        protected delegate Texture2D? ReadTexture2DMethod(string texturePath, string name);
        public const string MANIFEST_FILENAME = "manifest.json";
        protected class PackReadData
        {
            public string Key;
            public Dictionary<string, Dictionary<string, Catalog>> catalogs = new();
            public List<TextureEntry> textureEntries = new();

            public PackReadData(string key)
            {
                Key = key;
            }
        }
        protected class TextureEntry
        {
            public NamespaceID textureID;
            public string texturePath;
            public FilterMode filterMode;
            public List<SliceData> slices = new List<SliceData>();

            public TextureEntry(NamespaceID textureID, string texturePath)
            {
                this.textureID = textureID;
                this.texturePath = texturePath;
            }
        }
        protected class SliceData
        {
            public Rect rect;
            public Vector2 pivot;
            public float pixelsPerUnit;
            public uint extrude;
            public bool single;
            public SpriteMeshType meshType;
            public Vector4 border;
            public SpriteLookupKey spriteKey;

            public SliceData(SpriteLookupKey spriteKey)
            {
                this.spriteKey = spriteKey;
            }
        }
    }
}
